import{_ as e,c as t,o as i,ag as l}from"./chunks/framework._xRlcm3f.js";const _=JSON.parse('{"title":"分类体系","description":"","frontmatter":{},"headers":[],"relativePath":"guide/categories.md","filePath":"guide/categories.md","lastUpdated":1790228279000}'),r={name:"guide/categories.md"};function o(s,a,n,d,c,h){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="分类体系" tabindex="-1">分类体系 <a class="header-anchor" href="#分类体系" aria-label="Permalink to &quot;分类体系&quot;">​</a></h1><p>平台对文章的归类方式分为<strong>单选分类</strong>与<strong>多选分类</strong>两类，配置账号时按平台能力选择。</p><h2 id="单选分类" tabindex="-1">单选分类 <a class="header-anchor" href="#单选分类" aria-label="Permalink to &quot;单选分类&quot;">​</a></h2><p>只能选一个分类/专栏/空间。常见于使用「知识空间 / 专栏」概念的平台，例如：</p><ul><li>知乎（专栏）</li><li>哔哩哔哩（B 站，投稿分区）</li><li>语雀（知识库/知识空间）</li></ul><h2 id="多选分类" tabindex="-1">多选分类 <a class="header-anchor" href="#多选分类" aria-label="Permalink to &quot;多选分类&quot;">​</a></h2><p>可选择多个分类/标签。常见于使用「分类目录 / 标签」体系的平台，例如：</p><ul><li>WordPress（分类目录，支持多选）</li><li>博客园（博客分类）</li><li>通用 MetaWeblog 类平台</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>具体可用字段与取值因平台而异，以各平台配置页提示为准。</li><li>发布脚本（YAML/metadata）会按所选方式写入对应平台字段。</li></ul>',10)])])}const p=e(r,[["render",o]]);export{_ as __pageData,p as default};
